<template>
  <div class="row items-center">
    <span class="q-mr-sm">{{ $t(label || 'pagination_size') }}:</span>
    <q-select
      outlined
      dense
      :model-value="currentValue"
      :options="options"
      @update:model-value="handleChange"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';

const DEFAULT_PAGE_SIZE = 25;

export async function getSavedPaginationSize(settingsKey: string): Promise<number> {
  const settings_store = useSettingStore();
  const saved = await settings_store.getSetting(settingsKey);
  if (saved) {
    const size = Number(saved);
    return size <= 50 ? size : 50;
  }
  return DEFAULT_PAGE_SIZE;
}

export default defineComponent({
  name: 'GenericPaginationSettings',
  props: {
    settingsKey: {
      type: String,
      required: true,
    },
    label: {
      type: String,
      default: 'pagination_size',
    },
    options: {
      type: Array as PropType<string[]>,
      default: () => ['10', '20', '25', '50'],
    },
    modelValue: {
      type: String,
      default: '',
    },
  },
  emits: ['update:model-value'],
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { setUserPreferences } = settings_store;

    return {
      user_settings,
      loading_settings,
      setUserPreferences,
    };
  },
  computed: {
    currentValue(): string {
      if (this.modelValue) {
        return this.modelValue;
      }
      const saved = this.user_settings[this.settingsKey];
      return saved ? String(saved) : this.options[0] || '25';
    },
  },
  watch: {
    loading_settings: {
      handler(newVal: boolean, oldVal: boolean) {
        if (newVal === true && oldVal === false) {
          return;
        }
        this.syncFromSettings();
      },
    },
  },
  mounted() {
    this.syncFromSettings();
  },
  methods: {
    syncFromSettings() {
      if (!this.settingsKey) return;
      if (this.modelValue) return;
      const saved = this.user_settings[this.settingsKey];
      if (saved) {
        this.$emit('update:model-value', String(saved));
      }
    },
    async handleChange(newSize: string) {
      const size = Number(newSize);
      if (size > 50) return;

      this.$emit('update:model-value', newSize);

      if (!this.settingsKey) return;
      try {
        await this.setUserPreferences(this.settingsKey, size);
      } catch (err) {
        logError(err);
      }
    },
  },
});
</script>
